import json,sys,re,time
from pathlib import Path
from current_batch_ui import UI
x=json.load(sys.stdin);j=x['job_id'];code=x['code'];assert j in ['1518'] and re.fullmatch('[A-Za-z0-9]{8}',code);q=Path('/mnt/c/gecko_main/openclaw/application-queue');e=json.loads((q/j/'submission-result.json').read_text());route=json.loads((q/j/'application-form-route.json').read_text());assert e['outcome']=='verification_pending';u=UI(route['targetId']);s=u.snap();u.call(['type',u.ref(s,'textbox','Security code'),code,'--slowly']);u.call(['click',u.ref(s,'button','Submit application')]);time.sleep(1);r=u.call(['evaluate','--fn','() => ({url:location.href,title:document.title,text:document.body.innerText})']);(q/j/'after-verification-review.json').write_text(json.dumps(r,indent=2));f=r['result'];assert 'Thank you for applying' in f['title'] and 'Submit application' not in f['text'];e.update(outcome='confirmation_review',confirmation_url=f['url'],confirmation_text=f['text']);(q/j/'submission-result.json').write_text(json.dumps(e,indent=2));print(json.dumps({'id':j,'outcome':'confirmation_review','url':f['url'],'receipt':f['text'][:1300]}))

